// BootQuest kata module: a TESTABLE, self-contained adaptation (not a repo file) of relay-app @ 79e71dc:
//   server/Relay.Api/Controllers/HooksController.cs:85-130 (the idempotency branch, the run dispatch, LogDelivery: verbatim)
//   with the flow executor's contract from server/Relay.Infrastructure/Execution/FlowExecutor.cs (the steps run
//   first, the run row is saved at the end, :166).
// EF Core is replaced by a request-scoped context over one shared in-memory store that enforces the unique
// (FlowId, IdempotencyKey) index on save (a violating save throws a DbUpdateException stand-in and leaves the
// failed rows tracked, as EF does); token lookup, signatures and the HTTP plumbing are left out.
namespace Relay.Kata;

public enum RunStatus
{
    Succeeded,
    Failed,
}

public enum RunTrigger
{
    Webhook,
}

public enum WebhookDeliveryOutcome
{
    Delivered,
    Duplicate,
}

public sealed class Run
{
    public Guid Id { get; init; }
    public Guid FlowId { get; init; }
    public string? IdempotencyKey { get; init; }
    public RunStatus Status { get; init; }
}

public sealed class Webhook
{
    public Guid Id { get; init; } = Guid.NewGuid();
    public Guid WorkspaceId { get; init; } = Guid.NewGuid();
    public Guid FlowId { get; init; } = Guid.NewGuid();
    public DateTimeOffset? LastTriggeredAtUtc { get; set; }
}

public sealed class WebhookDelivery
{
    public Guid Id { get; init; }
    public Guid WebhookId { get; init; }
    public Guid WorkspaceId { get; init; }
    public DateTimeOffset ReceivedAtUtc { get; init; }
    public bool Success { get; init; }
    public WebhookDeliveryOutcome Outcome { get; init; }
    public Guid? RunId { get; init; }
    public string? Detail { get; init; }
}

/// <summary>Stand-in for EF Core's DbUpdateException (here: the unique idempotency index).</summary>
public sealed class DbUpdateException(string message) : Exception(message);

public interface IClock
{
    DateTimeOffset UtcNow { get; }
}

public sealed class FixedClock(DateTimeOffset now) : IClock
{
    public DateTimeOffset UtcNow { get; } = now;
}

/// <summary>The database every request shares: committed rows only.</summary>
public sealed class RelayStore
{
    public List<Run> Runs { get; } = [];
    public List<WebhookDelivery> Deliveries { get; } = [];
}

public sealed class RunQuery(RelayStore store)
{
    public RunQuery AsNoTracking() => this;

    public Task<Run?> FirstOrDefaultAsync(Func<Run, bool> predicate, CancellationToken ct) =>
        Task.FromResult(store.Runs.FirstOrDefault(predicate));

    public Task<Run> FirstAsync(Func<Run, bool> predicate, CancellationToken ct) =>
        Task.FromResult(store.Runs.First(predicate));
}

public sealed class TrackedSet<T>(List<T> pending)
{
    public void Add(T row) => pending.Add(row);
}

public sealed class ChangeTracker(Action clear)
{
    public void Clear() => clear();
}

/// <summary>One request-scoped RelayDbContext over the shared store.</summary>
public sealed class RelayDbContext(RelayStore store)
{
    private readonly List<Run> _pendingRuns = [];
    private readonly List<WebhookDelivery> _pendingDeliveries = [];

    public RunQuery Runs => new(store);

    public TrackedSet<Run> NewRuns => new(_pendingRuns);

    public TrackedSet<WebhookDelivery> WebhookDeliveries => new(_pendingDeliveries);

    public ChangeTracker ChangeTracker => new(() =>
    {
        _pendingRuns.Clear();
        _pendingDeliveries.Clear();
    });

    public Task<int> SaveChangesAsync(CancellationToken ct)
    {
        foreach (var run in _pendingRuns)
        {
            if (run.IdempotencyKey is not null && store.Runs.Any(r => r.FlowId == run.FlowId && r.IdempotencyKey == run.IdempotencyKey))
            {
                // the failed rows stay tracked (EF semantics): a retry would fail again until the tracker is cleared
                throw new DbUpdateException($"UNIQUE constraint failed: Runs.FlowId, Runs.IdempotencyKey ('{run.IdempotencyKey}')");
            }
        }

        var n = _pendingRuns.Count + _pendingDeliveries.Count;
        store.Runs.AddRange(_pendingRuns);
        store.Deliveries.AddRange(_pendingDeliveries);
        _pendingRuns.Clear();
        _pendingDeliveries.Clear();
        return Task.FromResult(n);
    }
}

public interface IFlowExecutor
{
    Task<Run?> RunFlowAsync(Guid flowId, RunTrigger trigger, string? body, CancellationToken ct, string? idempotencyKey = null);
}

/// <summary>Counts the flow's real-world side effects (HTTP calls, emails, writes) across all requests.</summary>
public sealed class SideEffects
{
    private int _count;

    public int Count => _count;

    public void Fire() => Interlocked.Increment(ref _count);
}

/// <summary>FlowExecutor's contract: every step runs (side effects fire), THEN the run row is saved.</summary>
public sealed class StepsThenSaveExecutor(RelayDbContext db, SideEffects effects, Func<Task>? beforeSave = null) : IFlowExecutor
{
    public async Task<Run?> RunFlowAsync(Guid flowId, RunTrigger trigger, string? body, CancellationToken ct, string? idempotencyKey = null)
    {
        effects.Fire();
        var run = new Run { Id = Guid.NewGuid(), FlowId = flowId, IdempotencyKey = idempotencyKey, Status = RunStatus.Succeeded };
        db.NewRuns.Add(run);
        if (beforeSave is not null)
        {
            await beforeSave();
        }

        await db.SaveChangesAsync(ct);
        return run;
    }
}

public sealed record ActionResult(int StatusCode, object? Value);

public sealed class HooksController
{
    private readonly RelayDbContext _db;
    private readonly IFlowExecutor _executor;
    private readonly IClock _clock;

    public HooksController(RelayDbContext db, IFlowExecutor executor, IClock clock)
    {
        _db = db;
        _executor = executor;
        _clock = clock;
    }

    /// <summary>Trigger, from the point the webhook is found, verified and its flow enabled.</summary>
    public async Task<ActionResult> Trigger(Webhook webhook, string? body, string? idempotencyKeyHeader, CancellationToken ct)
    {
        // Idempotency: a duplicate delivery keyed the same reuses the original run.
        var idempotencyKey = ReadIdempotencyKey(idempotencyKeyHeader);
        if (idempotencyKey is not null)
        {
            var existing = await _db.Runs.AsNoTracking()
                .FirstOrDefaultAsync(r => r.FlowId == webhook.FlowId && r.IdempotencyKey == idempotencyKey, ct);
            if (existing is not null)
            {
                await LogDelivery(webhook, true, WebhookDeliveryOutcome.Duplicate, existing.Id, "Deduplicated by idempotency key.", ct);
                await _db.SaveChangesAsync(ct);
                return Accepted(new { runId = existing.Id, status = existing.Status.ToString(), deduplicated = true });
            }
        }

        var run = await _executor.RunFlowAsync(
            webhook.FlowId, RunTrigger.Webhook, body, ct, idempotencyKey: idempotencyKey);

        webhook.LastTriggeredAtUtc = _clock.UtcNow;
        await LogDelivery(webhook, true, WebhookDeliveryOutcome.Delivered, run!.Id, null, ct);
        await _db.SaveChangesAsync(ct);

        return Accepted(new { runId = run.Id, status = run.Status.ToString(), deduplicated = false });
    }

    private static ActionResult Accepted(object value) => new(202, value);

    private Task LogDelivery(Webhook webhook, bool success, WebhookDeliveryOutcome outcome, Guid? runId, string? detail, CancellationToken ct)
    {
        _db.WebhookDeliveries.Add(new WebhookDelivery
        {
            Id = Guid.NewGuid(),
            WebhookId = webhook.Id,
            WorkspaceId = webhook.WorkspaceId,
            ReceivedAtUtc = _clock.UtcNow,
            Success = success,
            Outcome = outcome,
            RunId = runId,
            Detail = detail,
        });
        return Task.CompletedTask;
    }

    private static string? ReadIdempotencyKey(string? value) =>
        string.IsNullOrWhiteSpace(value) ? null : value.Trim();
}

