using Relay.Kata;

public sealed class WebhookIdempotencyTests
{
    private static readonly FixedClock Clock = new(new DateTimeOffset(2026, 1, 1, 12, 0, 0, TimeSpan.Zero));

    private static T Prop<T>(object value, string name) => (T)value.GetType().GetProperty(name)!.GetValue(value)!;

    private static HooksController Controller(RelayStore store, SideEffects effects, Func<Task>? beforeSave = null)
    {
        var db = new RelayDbContext(store);
        return new HooksController(db, new StepsThenSaveExecutor(db, effects, beforeSave), Clock);
    }

    /// <summary>
    /// Two deliveries with the same Idempotency-Key, interleaved the way ADR 0005's known gap describes:
    /// A executes its flow and is paused right before saving its run; B misses the lookup, executes, saves.
    /// </summary>
    private static async Task<(ActionResult? A, Exception? AThrew, ActionResult B, RelayStore Store, SideEffects Effects)> Race()
    {
        var store = new RelayStore();
        var effects = new SideEffects();
        var webhook = new Webhook();
        var paused = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var resume = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var a = Controller(store, effects, async () =>
        {
            paused.SetResult();
            await resume.Task;
        });
        var b = Controller(store, effects);

        var taskA = a.Trigger(webhook, "{\"order\":1}", "dupe-1", CancellationToken.None);
        await paused.Task;
        var resB = await b.Trigger(webhook, "{\"order\":1}", "dupe-1", CancellationToken.None);
        resume.SetResult();
        ActionResult? resA = null;
        var threw = await Record.ExceptionAsync(async () => resA = await taskA);
        return (resA, threw, resB, store, effects);
    }

    [Fact(DisplayName = "IdenticalSignedRequest_WithSameIdempotencyKey_ReusesTheSameRun (ported from server/Relay.Tests/WebhookSecurityBoundaryTests.cs:124)")]
    public async Task SequentialDuplicate_ReusesTheSameRun()
    {
        var store = new RelayStore();
        var effects = new SideEffects();
        var webhook = new Webhook();

        var first = await Controller(store, effects).Trigger(webhook, "{}", "signed-dupe-1", CancellationToken.None);
        var second = await Controller(store, effects).Trigger(webhook, "{}", "signed-dupe-1", CancellationToken.None);

        Assert.Equal(202, first.StatusCode);
        Assert.Equal(202, second.StatusCode);
        Assert.Equal(Prop<Guid>(first.Value!, "runId"), Prop<Guid>(second.Value!, "runId"));
        Assert.True(Prop<bool>(second.Value!, "deduplicated"));
        Assert.False(Prop<bool>(first.Value!, "deduplicated"));
        Assert.Equal(1, effects.Count);
    }

    [Fact(DisplayName = "Webhook_NoKey_AlwaysCreatesNewRun (ported from server/Relay.Tests/RetriesApiTests.cs:140)")]
    public async Task NoKey_AlwaysCreatesNewRun()
    {
        var store = new RelayStore();
        var effects = new SideEffects();
        var webhook = new Webhook();

        var first = await Controller(store, effects).Trigger(webhook, "{}", null, CancellationToken.None);
        var second = await Controller(store, effects).Trigger(webhook, "{}", null, CancellationToken.None);

        Assert.NotEqual(Prop<Guid>(first.Value!, "runId"), Prop<Guid>(second.Value!, "runId"));
        Assert.Equal(2, effects.Count);
    }

    [Fact(DisplayName = "concurrent duplicate: a delivery whose flow EXECUTED is never acknowledged as deduplicated (ADR 0005 known gap, docs/adr/0005-webhook-hmac-timestamp-idempotency.md:59)")]
    public async Task ExecutedDelivery_IsNeverReportedDeduplicated()
    {
        var (a, aThrew, b, _, effects) = await Race();

        Assert.Equal(2, effects.Count); // the race itself: both deliveries ran the flow
        Assert.False(Prop<bool>(b.Value!, "deduplicated"));
        Assert.True(
            aThrew is not null || !Prop<bool>(a!.Value!, "deduplicated"),
            "delivery A ran the flow's side effects, yet it was acknowledged as a deduplicated no-op");
    }

    [Fact(DisplayName = "concurrent duplicate: the delivery log never records Duplicate for an execution that really ran (ADR 0005 known gap)")]
    public async Task DeliveryLog_NeverHidesAnExecutedRun()
    {
        var (_, _, _, store, effects) = await Race();

        Assert.Equal(2, effects.Count);
        Assert.DoesNotContain(store.Deliveries, d => d.Outcome == WebhookDeliveryOutcome.Duplicate);
    }
}
